INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, nếu trả thêm phí thì có thể nâng lên ba năm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành, nếu máy lỗi hệ thống thì có được sửa tận nơi miễn phí không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong nội thành thì được sửa tận nơi miễn phí, còn ngoài phạm vi đó thì phải mang ra cửa hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Dạ em hiểu rồi, để em suy nghĩ thêm, lát nữa em quay lại thanh toán nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào chị, em thuê phòng đơn muốn đăng ký lắp mạng internet ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào em, em cho chị xin địa chỉ cụ thể để chị kiểm tra xem khu vực đó có phủ sóng đường truyền không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là khu chung cư gần trường đại học, tòa 3, phòng 502, phiền chị kiểm tra giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Xin lỗi em, cổng mạng khu chung cư của em tuần này đã dùng hết rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy à, vậy đợt cổng mạng tiếp theo mở lại là khi nào vậy chị?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở lại đợt mới, lúc đó chị có thể nhắc em đặt trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Dạ vâng, vậy phiền chị ba ngày sau liên hệ lại giúp em, chị vất vả rồi ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tao mới đổi điện thoại mới nè, chẳng biết chuyển dữ liệu từ máy cũ sang sao luôn á.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản mà, điện thoại có sẵn phần mềm chuyển máy, cứ làm theo từng bước là được thôi mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn, ảnh với file có copy sang đầy đủ hết không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Đầy đủ hết luôn, chỉ cần hai máy kết nối chung một WiFi thôi à.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_05','V347','阮明',5,'我还担心会丢失重要的学习资料。','wǒ hái dān xīn huì diū shī zhòng yào de xué xí zī liào。','Tao vẫn sợ mất mấy tài liệu học quan trọng lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_06','V347','小杨',6,'放心，我上次换机一点资料都没漏掉。','fàng xīn， wǒ shàng cì huàn jī yì diǎn zī liào dōu méi lòu diào。','Yên tâm đi, lần trước tao đổi máy có sót cái gì đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_07','V347','阮明',7,'太谢谢你了，等下我操作有问题再来问你吧。','tài xiè xiè nǐ le， děng xià wǒ cāo zuò yǒu wèn tí zài lái wèn nǐ ba。','Cảm ơn mày nhiều nha, lát nữa làm mà bí thì tao hỏi mày tiếp nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT348','S118','Cài đặt và đăng ký app dịch tiếng Trung',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V348','SIT348','P1','suon_se','tuy_y',NULL,'留学生常用翻译APP辅助学习中文，国内软件支持微信、QQ快捷登录，注册流程简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_01','V348','阮明',1,'有没有好用的翻译软件推荐我下载一下啊？','yǒu méi yǒu hǎo yòng de fān yì ruǎn jiàn tuī jiàn wǒ xià zài yī xià a？','Có app dịch nào xịn thì giới thiệu tao tải về xài với.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_02','V348','小林',2,'这款翻译APP特别适合留学生，离线也能用呢。','zhè kuǎn fān yì APP tè bié shì hé liú xué shēng， lí xiàn yě néng yòng ne。','App dịch này hợp với du học sinh lắm luôn, không có mạng cũng dùng được nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_03','V348','阮明',3,'下载之后注册需要绑定手机号吗？','xià zài zhī hòu zhù cè xū yào bǎng dìng shǒu jī hào ma？','Tải xong đăng ký có cần gắn số điện thoại không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_04','V348','小林',4,'只用微信一键登录就可以，不用额外注册啦。','zhǐ yòng wēi xìn yī jiàn dēng lù jiù kě yǐ， bù yòng é wài zhù cè la。','Chỉ cần đăng nhập bằng WeChat một cái là xong, khỏi cần đăng ký gì thêm luôn.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_05','V348','阮明',5,'还能拍照翻译课本上的汉字，对吗？','hái néng pāi zhào fān yì kè běn shàng de hàn zì， duì ma？','Còn chụp ảnh dịch chữ Hán trong sách giáo khoa được nữa hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_06','V348','小林',6,'没错，拍照翻译准确度很高，日常学习够用。','méi cuò， pāi zhào fān yì zhǔn què dù hěn gāo， rì cháng xué xí gòu yòng。','Đúng rồi đó, chụp ảnh dịch chuẩn lắm, dùng học hằng ngày là quá đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_07','V348','阮明',7,'太好了，我现在就下载安装试试吧。','tài hǎo le， wǒ xiàn zài jiù xià zài ān zhuāng shì shì ba。','Tuyệt quá, để tao tải cài đặt thử liền đây.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào anh, gói cước data của em hôm nay hết hạn rồi, em muốn gia hạn tại chỗ luôn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được, em đưa số thuê bao đây, anh kiểm tra các gói cước giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Bình thường em dùng data nhiều lắm, có gói dành cho sinh viên không giới hạn dung lượng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho sinh viên tháng này ngừng bán rồi, chỉ còn chọn gói thường thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','Ơ, vậy gói thường mỗi tháng bao nhiêu dung lượng, cước tháng bao nhiêu tiền vậy anh?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G data, cước tháng ba mươi chín tệ, giá rất hời đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Được, vậy em đăng ký gia hạn gói thường này luôn ạ.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Anh ơi, WiFi phòng em tự nhiên mất kết nối, phiền anh qua xem giúp em với.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, để anh kiểm tra modem quang với router trước, khả năng cao là dây bị lỏng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng vẫn chạy êm lắm, sáng nay tự nhiên mất mạng luôn ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Anh cắm chặt lại dây, rồi reset router lại là phục hồi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa vậy có phải trả thêm phí dịch vụ không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Trong thời gian bảo hành mạng thì đến tận nơi kiểm tra sửa chữa hoàn toàn miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, anh vất vả giúp em xử lý rồi nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào chị, em muốn chuyển tiền cho bạn học qua app ngân hàng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào em, em cần nhập số thẻ ngân hàng và tên của người nhận để đối chiếu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển tiền có giới hạn hạn mức không chị, em chuyển một lần ba nghìn tệ được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại sinh viên hạn mức chuyển tiền một ngày là năm mươi nghìn tệ, hoàn toàn không vấn đề gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi thì có tin nhắn báo cho cả hai bên không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều nhận được thông báo, tiện đối chiếu lại giao dịch đó em.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Em hiểu quy trình rồi ạ, cảm ơn chị đã giải thích nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào chị, người nhà tôi ở nước ngoài vừa gửi cho tôi một khoản sinh hoạt phí, tôi muốn làm thủ tục kết hối ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Anh vui lòng cho tôi xem hộ chiếu và thẻ ngân hàng, tôi kiểm tra tình trạng tiền ngoại tệ đã về tài khoản chưa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Vâng, giấy tờ đây ạ, khoản này chuyển vào khoảng chiều tối hôm qua.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi anh, khoản chuyển tiền này chưa được thanh toán bù trừ xong nên hôm nay tạm thời chưa rút được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ? Vậy phải đợi đến bao giờ mới đổi được sang nhân dân tệ ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống hoàn tất thanh toán bù trừ rồi, anh quay lại quầy làm thủ tục là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Vâng, sáng mai tôi qua sớm, phiền chị ghi chú giúp tôi nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì vậy, em không rành lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ vào trước, nhập mật khẩu, rồi chọn số tiền muốn rút là xong thôi mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Mỗi ngày rút được tối đa bao nhiêu tiền mặt vậy, có bị giới hạn không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','Hạn mức ATM mỗi ngày là hai mươi triệu, đủ xài sinh hoạt phí thoải mái luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhớ rút thẻ ra liền đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng rồi, để quá lâu không rút thẻ là máy tự nuốt thẻ đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nha, không thì em dễ quên lắm.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Chào chị, tôi bị mất thẻ ngân hàng, tôi cần báo mất và khóa thẻ khẩn cấp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Anh vui lòng cho biết họ tên, bốn số cuối thẻ ngân hàng và số chứng minh nhân dân ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Tôi ghi nhớ đầy đủ hết rồi, giờ tôi đọc cho chị kiểm tra nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm thời đóng băng thẻ của anh rồi, tiền sẽ không bị mất cắp đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau này muốn làm lại thẻ mới thì có phải ra quầy trực tiếp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng, anh mang theo hộ chiếu đến chi nhánh gần nhất là làm lại thẻ được ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn chị nhiều, may mà tôi gọi báo mất kịp thời.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào chị, tôi cần in bảng sao kê giao dịch thẻ ngân hàng khoảng nửa năm gần đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được ạ, anh đưa thẻ ngân hàng và hộ chiếu, tôi tra cứu và in giúp anh nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê như vậy có mất phí gì không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh in sao kê phục vụ mục đích du học thì được miễn phí đó anh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Tuyệt quá, tôi cần nộp cho trường làm chứng từ tài chính.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Tôi sẽ đóng dấu ngân hàng lên đây, trường sẽ chấp nhận trực tiếp không cần thêm gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn chị vất vả rồi, lát tôi lấy sao kê xong là về liền.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào anh, tôi muốn đổi mật khẩu rút tiền của thẻ ngân hàng ở máy tự phục vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Anh cắm thẻ vào, nhập mật khẩu cũ trước, rồi đặt mật khẩu mới sáu chữ số là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Tôi vừa nhập một lần rồi, máy báo hai lần mật khẩu không khớp nhau nè.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Tôi nhìn không rõ màn hình, hai lần gõ số không giống nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao đâu, anh làm lại một lần nữa, để ý kỹ số trên màn hình là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Được, để tôi làm từ từ, lần này chắc chắn để ý màn hình cẩn thận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công rồi, cảm ơn anh đứng bên cạnh hướng dẫn cho em nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Chào chị, nếu tôi chuyển tiền về tài khoản ở Việt Nam thì phí chuyển tính như thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí chuyển gồm hai phần, phí công thủ tục cố định và phí điện tín xuyên biên giới ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì mức phí có thay đổi theo không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Phí áp dụng theo mức cố định, không tăng giảm theo số tiền chuyển đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền về đến tài khoản ngân hàng ở nước ngoài của người nhận ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, nếu trúng ngày lễ thì thời gian thanh toán bù trừ sẽ lùi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi hiểu rõ hết rồi ạ, cảm ơn chị đã giải thích tỉ mỉ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理；商家责任退款自动审核，到账速度更快。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我要反馈一笔线上订单问题，支付扣款成功，至今没有收到包裹。','nǐ hǎo， wǒ yào fǎn kuì yī bǐ xiàn shàng dìng dān wèn tí， zhī fù kòu kuǎn chéng gōng， zhì jīn méi yǒu shōu dào bāo guǒ。','Chào chị, tôi muốn phản ánh một đơn hàng online, tiền đã bị trừ thanh toán thành công nhưng đến giờ vẫn chưa nhận được hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'您好，麻烦先提供一下完整订单编号，我调取后台物流配送记录哈。','nín hǎo， má fán xiān tí gōng yī xià wán zhěng dìng dān biān hào， wǒ diào qǔ hòu tái wù liú pèi sòng jì lù hā。','Chào anh, phiền anh cung cấp giúp mã đơn hàng đầy đủ, tôi tra lại thông tin vận chuyển ở hệ thống hậu đài nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单编号我复制在这里发给你，物流页面从下单当天一直显示待揽收状态呢。','dìng dān biān hào wǒ fù zhì zài zhè lǐ fā gěi nǐ， wù liú yè miàn cóng xià dān dàng tiān yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng tôi sao chép gửi chị đây, trang theo dõi vận chuyển từ lúc đặt hàng đến giờ vẫn báo trạng thái chờ lấy hàng.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'我调取仓库发货台账核对，查到是仓库工作人员漏打包商品，实在非常抱歉。','wǒ diào qǔ cāng kù fā huò tái zhàng hé duì， chá dào shì cāng kù gōng zuò rén yuán lòu dǎ bāo shāng pǐn， shí zài fēi cháng bào qiàn。','Tôi kiểm tra sổ sách xuất kho thì phát hiện là nhân viên kho đóng gói thiếu sót hàng của anh, thực sự rất xin lỗi anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'我下单已经七天，一直等待收货，耽误了我的使用计划，心里挺着急的。','wǒ xià dān yǐ jīng qī tiān， yì zhí děng dài shōu huò， dān wù le wǒ de shǐ yòng jì huà， xīn lǐ tǐng zháo jí de。','Tôi đặt hàng đã bảy ngày rồi, cứ chờ mãi mà chưa có hàng, ảnh hưởng đến kế hoạch sử dụng của tôi, trong lòng khá sốt ruột.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'针对漏发问题平台提供两种解决方案，您可以自由选择，没有强制要求。','zhēn duì lòu fā wèn tí píng tái tí gōng liǎng zhǒng jiě jué fāng àn， nín kě yǐ zì yóu xuǎn zé， méi yǒu qiáng zhì yāo qiú。','Đối với trường hợp thiếu hàng, bên nền tảng đưa ra hai phương án giải quyết, anh có thể tự chọn, không bắt buộc gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'那现在第一种方案补发商品、第二种全额退款，两种分别需要等待多久？','nà xiàn zài dì yī zhǒng fāng àn bǔ fā shāng pǐn、 dì èr zhǒng quán é tuì kuǎn， liǎng zhǒng fēn bié xū yào děng dài duō jiǔ？','Vậy phương án một là gửi bù hàng, phương án hai là hoàn tiền toàn bộ, mỗi cái phải đợi bao lâu vậy chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_08','V358','客服',8,'选择补发需要重新排单发货，仓库备货需要再等三天；退款申请提交当日原路返还资金。','xuǎn zé bǔ fā xū yào chóng xīn pái dān fā huò， cāng kù bèi huò xū yào zài děng sān tiān； tuì kuǎn shēn qǐng tí jiāo dāng rì yuán lù fǎn huán zī jīn。','Nếu chọn gửi bù thì phải sắp lịch giao hàng lại, kho chuẩn bị hàng cần thêm ba ngày; còn hoàn tiền thì nộp đơn ngày nào là tiền về theo đường cũ ngay ngày đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_09','V358','阮明',9,'我急需这件商品使用，不想再额外等待三天补发货品。','wǒ jí xū zhè jiàn shāng pǐn shǐ yòng， bù xiǎng zài é wài děng dài sān tiān bǔ fā huò pǐn。','Tôi đang cần dùng món hàng này gấp, không muốn đợi thêm ba ngày để nhận hàng bù nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_10','V358','客服',10,'我明白您的需求，那我直接为您提交全额退款售后申请。','wǒ míng bái nín de xū qiú， nà wǒ zhí jiē wèi nín tí jiāo quán é tuì kuǎn shòu hòu shēn qǐng。','Tôi hiểu nhu cầu của anh rồi, vậy tôi sẽ nộp đơn hoàn tiền toàn bộ cho anh luôn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_11','V358','阮明',11,'退款审核会不会需要人工排队，延迟好几天到账？','tuì kuǎn shěn hé huì bú huì xū yào rén gōng pái duì， yán chí hǎo jǐ tiān dào zhàng？','Việc duyệt hoàn tiền có phải xếp hàng xử lý thủ công không, có bị chậm về tài khoản mấy ngày không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_12','V358','客服',12,'漏发属于商家全责，退款自动审核，几分钟内就能完成资金返还。','lòu fā shǔ yú shāng jiā quán zé， tuì kuǎn zì dòng shěn hé， jǐ fēn zhōng nèi jiù néng wán chéng zī jīn fǎn huán。','Trường hợp thiếu hàng là lỗi hoàn toàn của người bán, hoàn tiền được duyệt tự động, chỉ vài phút là tiền về lại tài khoản thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_13','V358','阮明',13,'那就直接办理全额退款吧，我不想继续等待补发货物了。','nà jiù zhí jiē bàn lǐ quán é tuì kuǎn ba， wǒ bù xiǎng jì xù děng dài bǔ fā huò wù le。','Vậy làm hoàn tiền toàn bộ luôn đi, tôi không muốn đợi gửi bù hàng nữa.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_14','V358','客服',14,'申请已提交，您留意支付软件的到账通知即可。','shēn qǐng yǐ tí jiāo， nín liú yì zhī fù ruǎn jiàn de dào zhàng tōng zhī jí kě。','Đơn đã được nộp rồi, anh chú ý thông báo tiền về trên ứng dụng thanh toán là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_15','V358','阮明',15,'好，感谢快速处理我的售后投诉。','hǎo， gǎn xiè kuài sù chǔ lǐ wǒ de shòu hòu tóu sù。','Vâng, cảm ơn chị xử lý khiếu nại của tôi nhanh chóng.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chào chú, cháu muốn đến phố đi bộ trung tâm thành phố thì đón xe buýt tuyến nào ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra khỏi cửa rẽ phải, đến trạm bắt tuyến 12, điểm cuối chính là trung tâm thành phố luôn đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Đi một chuyến mất khoảng bao lâu vậy chú, có hay bị kẹt xe không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt xe thì bốn mươi phút, vào giờ tan tầm thì sẽ chậm hơn một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt có hỗ trợ quét mã trên điện thoại để lên xe, không cần làm thẻ cứng đúng không chú?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi, mở mã lên xe ra rồi quét là lên xe được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cảm ơn chú chỉ đường nha, giờ cháu ra trạm chờ xe luôn đây.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự động này nạp tiền vào thẻ tàu điện thế nào vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Bạn đặt thẻ lên vùng cảm ứng trước, rồi chọn số tiền cần nạp và quét mã thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Tôi quét mã thanh toán xong rồi mà máy báo nạp tiền thất bại nè.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại đã bị trừ tiền, nhưng số dư trong thẻ lại không tăng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Đừng lo, hệ thống bị chậm thôi, khoảng năm phút nữa kiểm tra lại số dư là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Thì ra là do hệ thống bị đơ, để lát nữa tôi xem lại số dư vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, không thì tôi chẳng biết làm sao luôn đó.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, tôi quét mã mở khóa xe đạp công cộng sao cứ báo mở khóa thất bại hoài vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Bạn xem thử bluetooth điện thoại đã bật chưa, đi xe là phải bật bluetooth đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth mở rồi mà, màn hình cứ hiện xe bị hỏng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là xe đó có vấn đề rồi, bạn bấm nút đổi xe khác là được ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Thì ra là vậy, tôi cứ tưởng tài khoản mình có vấn đề chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Ngoài đường có nhiều xe dự phòng lắm, đổi qua xe khác là mở khóa được liền à.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn bạn nhắc tôi nhiều lắm, không thì tôi phải đứng đây lâu lắm rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào anh, tôi muốn thuê một chiếc xe máy điện, chỉ dùng nửa ngày thôi có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Không vấn đề gì, nửa ngày ba mươi tệ, cần thế chấp hộ chiếu của anh để đăng ký nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Tôi đi xe ra khu du lịch ngoại ô, pin đi về có đủ dùng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy đi được năm mươi cây số, đi gần thế này thì thoải mái đủ dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ giữa đường hết pin thì cửa hàng có thiết bị sạc dự phòng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có sạc di động, anh có thể mang theo bên người để phòng khi cần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Được rồi, vậy giờ tôi đăng ký thuê xe luôn, phiền anh giúp giùm nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào bạn, tôi muốn dùng máy tự động mua một vé tàu cao tốc đi thành phố kế bên vào cuối tuần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Anh đặt hộ chiếu vào vùng đọc thẻ trước, rồi nhập ga đến là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn xong chuyến tàu rồi, nhưng hệ thống báo giấy tờ người nước ngoài không xác thực trực tuyến được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này anh phải ra quầy nhân viên, họ sẽ nhập thông tin thủ công cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy nhân viên có đông người xếp hàng không, chắc phải đợi lâu lắm không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Bây giờ không đông lắm đâu, khoảng mười phút là mua xong vé thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Được rồi, tôi ra quầy nhân viên ngay đây, cảm ơn bạn đã hướng dẫn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi có mua vé tàu cao tốc sáng mai, giờ muốn đổi sang chuyến buổi chiều ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Anh cho tôi xin hộ chiếu dùng để mua vé, để tôi kiểm tra vé còn trống giúp anh nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé như vậy có phải trả thêm phí gì không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ tàu chạy thì đổi vé lần đầu miễn phí, đổi lần thứ hai mới tính phí đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều vẫn còn chỗ trống đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Vẫn còn ghế hạng hai, để tôi đổi thông tin chuyến tàu cho anh luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị nhiều, thay đổi lịch trình đột xuất thế này thật ngại quá.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Bác tài ơi phiền bác chạy nhanh giùm chút, tôi khó chịu trong người cần đến bệnh viện gấp ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Yên tâm đi, tôi sẽ tránh mấy đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Xuống ngay cổng chính bệnh viện, không cần vào tầng hầm để xe được không bác?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Không vấn đề gì, khu vực đón trả khách tạm thời ở cổng chính có thể dừng ngắn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Tôi chóng mặt dữ lắm, phiền bác chạy êm êm chút nha.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, có gì khó chịu cứ nói với tôi bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn bác đã thông cảm cho tôi nhiều lắm, tới nơi tôi thanh toán ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào anh, cho tôi hỏi tuyến xe buýt số 18 tối nay chuyến cuối chạy lúc mấy giờ vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín giờ rưỡi, nhưng hôm nay tuyến điều chỉnh tạm thời nên chín giờ là hết chuyến rồi đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào chuyển xe khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể chuyển sang đi tàu điện ngầm, chuyến cuối của tàu điện phải mười một giờ mới ngừng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ ra ga tàu điện thì mất khoảng mấy phút vậy ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Khoảng bảy tám phút thôi, cứ đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL);
